import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {
    static int readAt(List<Integer> all, int[] pos) {
        if (pos[0] >= all.size()) {
            throw new NoSuchElementException();
        }
        return all.get(pos[0]++);
    }

    public static void main(String[] args) throws IOException {
        List<Integer> all = new ArrayList<>();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine()) != null) {
            StringTokenizer tokenizer = new StringTokenizer(line);
            while (tokenizer.hasMoreTokens()) {
                all.add(Integer.parseInt(tokenizer.nextToken()));
            }
        }

        if (all.size() < 2) {
            throw new NoSuchElementException();
        }

        int n = all.get(0);
        int btcAmount = all.get(1);
        int[] btcCosts = new int[100];
        int even = 0;
        int odd = 0;
        int right = 0;
        int[] pos = {2};

        for (int i = 0; i < n; i++) {
            int left;
            if (right == 0) {
                left = readAt(all, pos);
            } else {
                left = right;
                right = 0;
            }

            if (left % 2 == 0) {
                even++;
            } else {
                odd++;
            }

            if (even == odd && i != n - 1) {
                right = readAt(all, pos);
                int btcCost = Math.abs(left - right);
                btcCosts[btcCost] += 1;
                even = 0;
                odd = 0;
            }
        }

        int sawedAmount = 0;
        int currentBTCCost = 0;
        for (int i = 0; i < 100; i++) {
            for (int j = 0; j < btcCosts[i]; j++) {
                currentBTCCost += i;
                if (currentBTCCost <= btcAmount) {
                    sawedAmount++;
                } else {
                    break;
                }
            }
        }
        System.out.println(sawedAmount);
    }
}
